const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Pantanal region (rough bounding box)
  const pantanal = ee.Geometry.Rectangle([-58.0, -18.5, -54.0, -15.5]);

  // 2. MODIS Aqua fire product
  const modisAqua = ee.ImageCollection('MODIS/006/MYD14A1');

  // Helper: count fire pixels in an image (FireMask >= 4)
  function countFirePixels(img) {
    const fire = img.select('FireMask').gte(4).unmask(0);
    return fire.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: pantanal,
      scale: 1000,
      maxPixels: 1e9,
    }).get('FireMask');
  }

  // 3. Get fire count for June 11, 2024
  const date2024 = '2024-06-11';
  const dailyCol = modisAqua.filterDate(date2024, '2024-06-12').filterBounds(pantanal);
  const dailySize = dailyCol.size().getInfo();
  if (dailySize === 0) {
    console.log('No MODIS Aqua image for June 11, 2024.');
    console.log('<answer>C1</answer>');
    return;
  }
  const dailyImg = dailyCol.first();
  const dailyCount = countFirePixels(dailyImg).getInfo();
  if (dailyCount === null || dailyCount === undefined) {
    console.log('Failed to compute fire count for June 11, 2024.');
    console.log('<answer>C3</answer>');
    return;
  }

  // 4. Compute historical June totals (2000-2023)
  const historicalTotals = [];
  for (let year = 2000; year <= 2023; year++) {
    const juneStart = ee.Date.fromYMD(year, 5, 1); // JS months are 0-indexed? No, in EE, months are 1-indexed? Actually, fromYMD expects month 1-12.
    const juneEnd = ee.Date.fromYMD(year, 6, 1);
    const col = modisAqua.filterDate(juneStart, juneEnd).filterBounds(pantanal);
    const size = col.size().getInfo();
    let total = 0;
    if (size > 0) {
      // Create a composite summing daily fire masks
      const monthlyComposite = col.select('FireMask').map(img => 
        img.gte(4).unmask(0)
      ).sum();
      const monthlyCount = monthlyComposite.reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: pantanal,
        scale: 1000,
        maxPixels: 1e9,
      }).get('FireMask').getInfo();
      if (monthlyCount !== null && monthlyCount !== undefined) {
        total = monthlyCount;
      } else {
        // If reduceRegion fails, set total to 0 (or treat as no data?)
        total = 0;
      }
    }
    historicalTotals.push(total);
  }

  // 5. Find maximum historical June total
  const maxHistorical = Math.max(...historicalTotals);
  const maxYear = 2000 + historicalTotals.indexOf(maxHistorical);

  // 6. Print concise evidence
  console.log(`2024-06-11 fire count: ${dailyCount}`);
  console.log(`Max historical June total (2000-2023): ${maxHistorical} (in ${maxYear})`);

  // 7. Validate and output answer
  if (dailyCount === null || maxHistorical === null || 
      isNaN(dailyCount) || isNaN(maxHistorical)) {
    console.log('<answer>C3</answer>');
  } else if (dailyCount > maxHistorical) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
